import { handleOptions, jsonResponse, errorResponse } from '../_shared/cors.ts';
import { clientIp } from '../_shared/referral-crypto.ts';
import { supabaseService } from '../_shared/referral-db.ts';
import { bindPendingReferral } from '../_shared/referral-pending.ts';
import { assertPublicApiRateLimit } from '../_shared/referral-rate-limit.ts';
import { assertPublicBrowserOrigin } from '../_shared/referral-public-guard.ts';

Deno.serve(async (req) => {
  const options = handleOptions(req);
  if (options) return options;

  if (req.method !== 'POST') {
    return errorResponse(req, 'Method not allowed', 405);
  }

  try {
    const body = await req.json();
    const refCode = String(body?.ref_code ?? '');
    const deviceFp = String(body?.device_fp ?? '');

    assertPublicBrowserOrigin(req);
    const supabase = supabaseService();
    const ip = clientIp(req);
    await assertPublicApiRateLimit(supabase, ip, 'bind-pending');
    const result = await bindPendingReferral(supabase, {
      refCode,
      deviceFp,
      signupIp: clientIp(req),
      userAgent: req.headers.get('user-agent') ?? '',
    });

    return jsonResponse(req, { success: true, ...result });
  } catch (e) {
    const msg = e instanceof Error ? e.message : 'Error';
    const status = msg.includes('Demasiados') ? 429
      : msg.includes('Origen') ? 403
      : 400;
    return errorResponse(req, msg, status);
  }
});

const DEFAULT_ORIGINS = [
  'https://arcusx.pro',
  'https://www.arcusx.pro',
  'http://localhost:5173',
  'http://127.0.0.1:5173',
];

export function corsHeaders(req: Request): HeadersInit {
  const origin = req.headers.get('Origin') ?? '';
  const allowed = Deno.env.get('REFERRAL_CORS_ORIGINS')?.split(',').map((s) => s.trim()) ??
    DEFAULT_ORIGINS;
  const ok = allowed.includes(origin) || allowed.includes('*');
  return {
    'Access-Control-Allow-Origin': ok ? (origin || allowed[0]) : allowed[0],
    'Access-Control-Allow-Headers':
      'authorization, x-client-info, apikey, content-type, x-referral-internal-secret',
    'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  };
}

export function handleOptions(req: Request): Response | null {
  if (req.method === 'OPTIONS') {
    return new Response(null, { status: 204, headers: corsHeaders(req) });
  }
  return null;
}

export function jsonResponse(
  req: Request,
  body: unknown,
  status = 200,
): Response {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders(req), 'Content-Type': 'application/json' },
  });
}

export function errorResponse(
  req: Request,
  message: string,
  status = 400,
): Response {
  return jsonResponse(req, { success: false, message }, status);
}

const encoder = new TextEncoder();

function salt(): string {
  return Deno.env.get('REFERRAL_HASH_SALT') ?? 'arcusx-referral-v1';
}

export async function sha256Hex(input: string): Promise<string> {
  const data = encoder.encode(input);
  const hash = await crypto.subtle.digest('SHA-256', data);
  return Array.from(new Uint8Array(hash))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('');
}

export async function hashWithSalt(value: string): Promise<string> {
  if (!value?.trim()) return '';
  return sha256Hex(`${salt()}:${value.trim().toLowerCase()}`);
}

export function normalizeRefCode(code: string): string {
  return code.trim().toUpperCase().replace(/\s+/g, '-');
}

export function clientIp(req: Request): string {
  const forwarded = req.headers.get('x-forwarded-for');
  if (forwarded) return forwarded.split(',')[0]?.trim() ?? '';
  return req.headers.get('cf-connecting-ip') ??
    req.headers.get('x-real-ip') ??
    '';
}

import { createClient, type SupabaseClient } from '@supabase/supabase-js';

export function supabaseService(): SupabaseClient {
  const url = Deno.env.get('SUPABASE_URL') ??
    Deno.env.get('ARCUSX_SUPABASE_URL');
  const key = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ??
    Deno.env.get('ARCUSX_SUPABASE_SERVICE_ROLE_KEY');
  if (!url || !key) {
    throw new Error(
      'Supabase URL/service key requeridos (SUPABASE_* o ARCUSX_SUPABASE_*)',
    );
  }
  return createClient(url, key, {
    auth: { persistSession: false, autoRefreshToken: false },
  });
}

export async function refreshPartnerDaily(
  supabase: SupabaseClient,
  partnerId: string,
  statDate: string,
): Promise<void> {
  await supabase.rpc('referral_refresh_daily_totals', {
    p_partner_id: partnerId,
    p_stat_date: statDate,
  });
}

export async function bumpCodeCounters(
  supabase: SupabaseClient,
  codeId: string,
  valid: boolean,
): Promise<void> {
  const { data: row } = await supabase
    .from('referral_codes')
    .select('signup_count, valid_signup_count')
    .eq('id', codeId)
    .single();

  if (!row) return;

  await supabase
    .from('referral_codes')
    .update({
      signup_count: (row.signup_count ?? 0) + 1,
      valid_signup_count: valid
        ? (row.valid_signup_count ?? 0) + 1
        : row.valid_signup_count,
      updated_at: new Date().toISOString(),
    })
    .eq('id', codeId);
}

import type { SupabaseClient } from '@supabase/supabase-js';
import { hashWithSalt, normalizeRefCode } from './referral-crypto.ts';

const DEVICE_FP_RE = /^ax-[a-z0-9]+-[a-z0-9]+$/i;
const BIND_RATE_LIMIT_PER_IP_HOUR = 40;

export function assertValidDeviceFp(deviceFp: string): void {
  const fp = deviceFp?.trim() ?? '';
  if (!DEVICE_FP_RE.test(fp) || fp.length > 80) {
    throw new Error('device_fp inválido');
  }
}

export async function assertActiveReferralCode(
  supabase: SupabaseClient,
  refCode: string,
): Promise<void> {
  const code = normalizeRefCode(refCode);
  const { data: row } = await supabase
    .from('referral_codes')
    .select('id, expires_at, referral_partners!inner(is_active)')
    .eq('code', code)
    .eq('is_active', true)
    .maybeSingle();

  if (!row) throw new Error('Código no válido');

  const partner = row.referral_partners as { is_active: boolean };
  if (!partner?.is_active) throw new Error('Código no válido');

  if (row.expires_at && new Date(row.expires_at) < new Date()) {
    throw new Error('Código expirado');
  }
}

async function assertBindRateLimit(
  supabase: SupabaseClient,
  signupIp: string,
): Promise<void> {
  if (!signupIp?.trim()) return;
  const ipHash = await hashWithSalt(signupIp);
  if (!ipHash) return;
  const since = new Date(Date.now() - 60 * 60 * 1000).toISOString();
  const { count } = await supabase
    .from('referral_pending_attributions')
    .select('device_fp', { count: 'exact', head: true })
    .eq('signup_ip_hash', ipHash)
    .gte('created_at', since);
  if ((count ?? 0) >= BIND_RATE_LIMIT_PER_IP_HOUR) {
    throw new Error('Demasiados intentos; espera un momento');
  }
}

export interface PendingBindInput {
  refCode: string;
  deviceFp: string;
  signupIp?: string;
  userAgent?: string;
}

export async function bindPendingReferral(
  supabase: SupabaseClient,
  input: PendingBindInput,
): Promise<{ ref_code: string }> {
  const refCode = normalizeRefCode(input.refCode);
  const deviceFp = input.deviceFp?.trim() ?? '';
  if (!refCode || !deviceFp) {
    throw new Error('ref_code y device_fp requeridos');
  }
  assertValidDeviceFp(deviceFp);
  await assertActiveReferralCode(supabase, refCode);
  await assertBindRateLimit(supabase, input.signupIp ?? '');

  const signupIpHash = input.signupIp ? await hashWithSalt(input.signupIp) : null;
  const userAgentHash = input.userAgent ? await hashWithSalt(input.userAgent) : null;
  const expiresAt = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString();

  const { error } = await supabase.from('referral_pending_attributions').upsert(
    {
      device_fp: deviceFp,
      ref_code: refCode,
      signup_ip_hash: signupIpHash,
      user_agent_hash: userAgentHash,
      expires_at: expiresAt,
      claimed_at: null,
      supabase_user_id: null,
    },
    { onConflict: 'device_fp' },
  );

  if (error) throw new Error(error.message);
  return { ref_code: refCode };
}

export async function resolvePendingRefCode(
  supabase: SupabaseClient,
  deviceFp: string,
): Promise<string | null> {
  const fp = deviceFp?.trim();
  if (!fp) return null;

  const { data } = await supabase
    .from('referral_pending_attributions')
    .select('ref_code, expires_at, claimed_at')
    .eq('device_fp', fp)
    .maybeSingle();

  if (!data?.ref_code || data.claimed_at) return null;
  if (data.expires_at && new Date(data.expires_at) < new Date()) return null;
  return normalizeRefCode(data.ref_code);
}

export async function markPendingClaimed(
  supabase: SupabaseClient,
  deviceFp: string,
  supabaseUserId: string,
): Promise<void> {
  const fp = deviceFp?.trim();
  if (!fp) return;
  await supabase
    .from('referral_pending_attributions')
    .update({
      claimed_at: new Date().toISOString(),
      supabase_user_id: supabaseUserId,
    })
    .eq('device_fp', fp);
}

import type { SupabaseClient } from '@supabase/supabase-js';
import { hashWithSalt } from './referral-crypto.ts';

const LIMITS: Record<string, number> = {
  'resolve-code': 120,
  'bind-pending': 40,
};

export async function assertPublicApiRateLimit(
  supabase: SupabaseClient,
  signupIp: string,
  endpoint: string,
): Promise<void> {
  const ip = signupIp?.trim();
  if (!ip) return;

  const maxPerHour = LIMITS[endpoint] ?? 60;
  const ipHash = await hashWithSalt(ip);
  if (!ipHash) return;

  const since = new Date(Date.now() - 60 * 60 * 1000).toISOString();
  const { count } = await supabase
    .from('referral_api_hits')
    .select('id', { count: 'exact', head: true })
    .eq('ip_hash', ipHash)
    .eq('endpoint', endpoint)
    .gte('created_at', since);

  if ((count ?? 0) >= maxPerHour) {
    throw new Error('Demasiados intentos; espera un momento');
  }

  await supabase.from('referral_api_hits').insert({
    ip_hash: ipHash,
    endpoint,
  });
}

const DEFAULT_ORIGINS = [
  'https://arcusx.pro',
  'https://www.arcusx.pro',
  'http://localhost:5173',
  'http://127.0.0.1:5173',
];

function allowedOrigins(): string[] {
  const extra = Deno.env.get('REFERRAL_CORS_ORIGINS')?.split(',').map((s) => s.trim()) ??
    [];
  return [...DEFAULT_ORIGINS, ...extra].filter(Boolean);
}

/**
 * Endpoints pre-login: rechaza curl sin Origin/Referer de arcusx (no es secreto, sube la barra).
 */
export function assertPublicBrowserOrigin(req: Request): void {
  const allowed = allowedOrigins();
  const origin = req.headers.get('Origin')?.trim() ?? '';
  if (origin && allowed.includes(origin)) return;

  const referer = req.headers.get('Referer')?.trim() ?? '';
  if (referer) {
    for (const base of allowed) {
      if (referer.startsWith(base)) return;
    }
  }

  throw new Error('Origen no permitido');
}

/** Respuesta genérica: no revelar si el código existe, expiró o el partner está inactivo. */
export function invalidCodePayload() {
  return { success: true, valid: false as const };
}
